import sys

def main():
    input = sys.stdin.buffer.readline
    H, W = map(int, input().split())
    N = 1 << W

    count = [0] * N
    for _ in range(H):
        mask = int(input().strip(), 2)
        count[mask] += 1

    cost = [0] * N
    for mask in range(N):
        ones = mask.bit_count()
        cost[mask] = min(ones, W - ones)

    def fwht(a):
        a = a[:]
        h = 1
        n = len(a)
        while h < n:
            for i in range(0, n, h * 2):
                for j in range(i, i + h):
                    x = a[j]
                    y = a[j + h]
                    a[j] = x + y
                    a[j + h] = x - y
            h *= 2
        return a

    fc = fwht(count)
    ff = fwht(cost)

    conv = [fc[i] * ff[i] for i in range(N)]
    ans_values = fwht(conv)

    ans = min(v // N for v in ans_values)
    print(ans)

if __name__ == "__main__":
    main()
